package dev.theredstonee.trsclient.core.hud.miniplayer;
import dev.theredstonee.trsclient.core.module.TrsModules;
import dev.theredstonee.trsclient.core.config.ConfigStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.*;
class MiniPlayerTest {
 @TempDir Path dir;
 @Test void hiddenStatesAvoidRenderingAndEditorCanPreviewDisabled(){MiniPlayerModule m=new MiniPlayerModule();assertTrue(m.shouldDraw(false,true,false,false,false,true));assertFalse(m.shouldDraw(false,true,true,true,false,true));assertFalse(m.shouldDraw(false,true,true,false,true,true));assertFalse(m.shouldDraw(false,true,true,false,false,false));assertFalse(m.shouldDraw(true,false,true,false,false,true));m.visibility.set(MiniPlayerModule.Visibility.MOVEMENT);assertFalse(m.shouldDraw(false,true,false,false,false,true));assertTrue(m.shouldDraw(false,true,true,false,false,true));m.setEnabled(false);assertTrue(m.shouldDraw(true,true,false,true,true,true));m.opacity.set(0);assertFalse(m.shouldDraw(true,true,true,false,false,true));}
 @Test void updateRateAffectsWidgetOnlyAndWorldChangesInvalidate(){MiniPlayerModule m=new MiniPlayerModule();MiniPlayerState s=new MiniPlayerState();Object w=new Object(),p=new Object();assertTrue(s.update(w,p,0,true,1_000_000_000L,m));assertFalse(s.update(w,p,0,true,1_010_000_000L,m));assertTrue(s.update(w,p,0,true,1_040_000_000L,m));assertFalse(s.update(w,p,0,false,1_100_000_000L,m));assertTrue(s.update(new Object(),p,0,false,1_101_000_000L,m));s.invalidate();assertTrue(s.update(w,p,0,false,1_102_000_000L,m));}
 @Test void manualAngleConvergesAndLayerScopeRestores(){MiniPlayerModule m=new MiniPlayerModule();m.angle.set(MiniPlayerModule.Angle.MANUAL);m.rotation.set(90);MiniPlayerState s=new MiniPlayerState();Object w=new Object(),p=new Object();for(int i=1;i<100;i++)s.update(w,p,0,false,i*100_000_000L,m);assertEquals(90,s.yaw(),.06);assertNull(MiniPlayerRenderScope.current());MiniPlayerModule old=MiniPlayerRenderScope.enter(m);try{assertSame(m,MiniPlayerRenderScope.current());}finally{MiniPlayerRenderScope.restore(old);}assertNull(MiniPlayerRenderScope.current());}
 @Test void settingsPersistAndFreshNetworkingDoesNotOverrideExistingChoices() throws Exception {TrsModules a=new TrsModules(true);assertFalse(a.fastConnect.isEnabled());assertFalse(a.netOptimize.isEnabled());a.fastConnect.setEnabled(true);a.netOptimize.setEnabled(true);a.miniPlayer.opacity.set(65);a.miniPlayer.armor.set(false);a.miniPlayer.angle.set(MiniPlayerModule.Angle.SIDE);a.miniPlayer.position().offsetX=.54;ConfigStore store=new ConfigStore(dir.resolve("config.json"));store.save(a.registry);TrsModules b=new TrsModules(true);store.load(b.registry);assertTrue(b.fastConnect.isEnabled());assertTrue(b.netOptimize.isEnabled());assertEquals(65,b.miniPlayer.opacity.get());assertFalse(b.miniPlayer.armor.get());assertEquals(MiniPlayerModule.Angle.SIDE,b.miniPlayer.angle.get());assertEquals(.54,b.miniPlayer.position().offsetX);}
}
